<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,newKey} from '../api'
import {useRequestScope} from '../platform/request-scope'
import type {PublicationStatus,AuthorValue,PublicCard} from './types'
import './authoring.css'
interface ReviewItem{publication:PublicationStatus;card:PublicCard;snapshot:{value:AuthorValue;attribution:string};reports:{id:string;reason:string}[]}
const capture=useRequestScope(),items=ref<ReviewItem[]>([]),total=ref(0),offset=ref(0),notes=ref<Record<string,string>>({}),busy=ref(false),error=ref(''),notice=ref('')
async function load(){const scope=capture();busy.value=true;error.value='';try{const result=await api<{items:ReviewItem[];total:number}>('/authoring/moderation?offset='+offset.value+'&limit=10');if(scope.valid()){items.value=result.items;total.value=result.total}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function review(item:ReviewItem,decision:string){const scope=capture();busy.value=true;error.value='';try{await api('/authoring/moderation/'+item.publication.id,{method:'POST',key:newKey(),body:{expectedVersion:item.publication.version,decision,note:notes.value[item.publication.id]||''}});if(scope.valid()){notice.value='审核结果已保存。';await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function page(delta:number){offset.value=Math.max(0,offset.value+delta);await load()}
onMounted(load)
</script>
<template><section class="workspace-card"><h2>公开作品审核与举报</h2><p>逐项检查公开介绍、封面、完整世界设定和来源说明，再批准或退回。新版批准前，旧版保持原公开状态。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在读取或保存审核…</p><p v-if="!busy&&!items.length">没有待处理作品或举报。</p><article v-for="item in items" :key="item.publication.id" class="public-review"><h3>{{item.card.title}}</h3><p>{{item.card.summary}}</p><small>{{item.card.authorName}} · 作者版本 {{item.card.version}} · {{item.publication.state}}</small><p>来源：{{item.snapshot.attribution}}</p><img v-if="item.snapshot.value.coverDataUrl" :src="item.snapshot.value.coverDataUrl" :alt="item.card.title+'待审核封面'" style="max-width:180px;max-height:240px"><details><summary>完整待审核内容</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{JSON.stringify(item.snapshot,null,2)}}</pre></details><p v-for="report in item.reports" :key="report.id" class="product-hint">举报：{{report.reason}}</p><label>审核说明<textarea v-model="notes[item.publication.id]" maxlength="1000" rows="3"></textarea></label><div class="public-actions"><button v-if="item.publication.state==='pending'" class="primary" :disabled="busy||(notes[item.publication.id]||'').trim().length<3" @click="review(item,'approve')">批准公开</button><button v-if="item.publication.state==='pending'" :disabled="busy||(notes[item.publication.id]||'').trim().length<3" @click="review(item,'reject')">退回修改</button><button v-if="item.publication.live" :disabled="busy||(notes[item.publication.id]||'').trim().length<3" @click="review(item,'remove')">下架并处理举报</button></div></article><nav v-if="total>10" class="public-pagination"><button :disabled="busy||offset===0" @click="page(-10)">上一页</button><span>{{offset+1}} / {{total}}</span><button :disabled="busy||offset+10>=total" @click="page(10)">下一页</button></nav></section></template>
